def _to_fraction(s: str) -> Fraction:
    """Parse a canonical fraction string, incl. mixed numbers like '2 1/2'."""
    s = s.strip()
    if " " in s:
        whole, frac = s.split(" ", 1)
        return int(whole) + Fraction(frac)
    return Fraction(s)


